-- تعميم 10-2014.doc  [inferred from date mentioned in body text (NEEDS REVIEW)]
INSERT INTO public.official_letters (number, recipient, attention, date, subject, category, body, signer_name, signer_title, use_letterhead)
VALUES (
  (SELECT COALESCE(MAX(number),0)+1 FROM public.official_letters),
  'موظفي مؤسسة الحياة العلمية',
  NULL,
  '2014-07-28',
  'تعميم 10/4201',
  'circular',
  '<p style="text-align:center"><b style="font-size:20px">تعميم 10/4201</b></p>
<p>الى الموظفين الكرام يرجى العلم بما يلي :</p>
<p>كل عام وانتم بخير بمناسبة شهر رمضان وعيد الفطر نرجو العلم بما يلي :</p>
<ol>
<li>عطلة عيد الفطر من يوم الاثنين 28-07-2014 ولغاية يوم الخميس 31-07-2014 ويكون اول ايام الدوام هو يوم السبت 02-07-2014</li>
<li>الغاء خصومات شهر 7-2014 اكراما لشهر رمضان المبارك</li>
<li>سوف يتم اعادة احتساب الدوام وخصومات التاخير  ابتداءا من شهر 8-2014 حسب النظام الداخلي للمؤسسة راجيا عدم الاحراج او المراجعة بعد هذا التاخير في اية خصومات سوف يتم حسمها بسبب التاخير  ونرجو من الجميع الالتزام بالدوام وعدم التاخر لتجنب اية حسومات سوف يتم اقتطاعها من الراتب وسوف يتم اعتماد كرت الدوام المختوم اليا لاحتساب التاخير ونكرر بعدم الاحراج بالمراجعة بسبب خصومات التاخير .</li>
<li>ارجو التكرم بعدم طلب مغادرة قبل وقت انتهاء الدوام الرسمي وعدم الاحراج وعدم التطرق لموضوع المغادرة والا تعتبر مغادرة قبل وقت الدوام ويتم احتساب الخصومات حسب القانون الداخلي ويتم المغادرة قبل انتهاء الدوام بتوجيه شفوي من الدكتور محمد من غير طلب من الموظف</li>
</ol>
',
  'الدكتور محمد عقاب الجوابرة',
  'الادارة',
  true
);

