-- تعميم 2-2012.doc  [NO DATE IN TEXT — defaulted to Jan 1 of filename year (NEEDS REVIEW)]
INSERT INTO public.official_letters (number, recipient, attention, date, subject, category, body, signer_name, signer_title, use_letterhead)
VALUES (
  (SELECT COALESCE(MAX(number),0)+1 FROM public.official_letters),
  'موظفي مؤسسة الحياة العلمية',
  NULL,
  '2012-01-01',
  'تعميم 2/2012',
  'circular',
  '<p style="text-align:center"><b style="font-size:20px">تعميم 2/2012</b></p>
<p>بالاشارة الى الكتاب الموجه الى المدير نرجو العلم بان الدوام الرسمي خلال شهر رمضان المبارك هو من الساعة التاسعة والنصف صباحا ولغاية الساعة الرابعة مساءا علما ان ايام الاسبوع كلها دوام عدا يوم الجمعة عطلة رسمية واي تاخير سوف يتم العمل بنظام المؤسسة الداخلي ليتم احتساب اي تاخير او عطلة .</p>
<p>ويوم السبت الدوام من الساعة العاشرة والنصف صباحا ولغاية الرابعة عصرا .</p>
<p>نرجو عدم الاحراج ويعتبر هذا القرار قطعيا.</p>
<p>وكل عام وانتم بخير</p>
',
  'الدكتور محمد عقاب الجوابرة',
  'الادارة',
  true
);

-- تعميم 3-2012.doc  [NO DATE IN TEXT — defaulted to Jan 1 of filename year (NEEDS REVIEW)]
INSERT INTO public.official_letters (number, recipient, attention, date, subject, category, body, signer_name, signer_title, use_letterhead)
VALUES (
  (SELECT COALESCE(MAX(number),0)+1 FROM public.official_letters),
  'موظفي مؤسسة الحياة العلمية',
  NULL,
  '2012-01-01',
  'تعميم 3/2012',
  'circular',
  '<p style="text-align:center"><b style="font-size:20px">تعميم 3/2012</b></p>
<p>الى حميع الموظفين الكرام يرجى العلم بما يلي :</p>
<ol>
<li>مسؤول الدوام فقط هو فهد العطيات لذلك اي مسائل بالنسبة لكروت الدوام وتنسيق الاجازات والمغادرة والحضور نرجو التنسيق فقط مع فهد ولا يوجد اي اعتبار لاي اتصال او تبليغ ما لم يكن مباشرة مع مسؤول الدوام</li>
<li>بالنسبة للاجازات لا بد من التوقيع على النموذج المخصص للاجازة قبل اخذ الاجازة ليتم اخذ الموافقات من الادارة وايه اجازة غير مرفقة بالنموذج سوف يتم حسم مبلغ 20 دينار حسب النظام الداخلي للمؤسسة</li>
<li>الاجازات الاضطرارية التي يتم السماح بها كحد اقصى هي سبعة ايام في السنة فقط وبخلاف ذلك يتم تطبيق النظام الداخلي</li>
<li>الاجازة الاضطرارية هي فقط الاجازة التي يتم اخذها في نفس اليوم ويتم تقديم النموذج المخصص لذلك في اليوم التالي وتقديم التبرير المناسب لتلك الاجازة وثم تنظر الادارة في سبب الاجازة والتبرير وللادارة الحق في احتساب تلك الاجازة او حسمها او تطبيق الخصم</li>
<li>اي موظف يقوم بختم الكرت لموظف اخر دون علم مسؤول الدوام يتم حسم 10 دنانير من الموظف الذي حسم حسب النظام الداخلي</li>
</ol>
',
  'الدكتور محمد عقاب الجوابرة',
  'الادارة',
  true
);

