-- قرار 1.doc  [explicit "التاريخ" line]
INSERT INTO public.official_letters (number, recipient, attention, date, subject, category, body, signer_name, signer_title, use_letterhead)
VALUES (
  (SELECT COALESCE(MAX(number),0)+1 FROM public.official_letters),
  'محمود مصطفى العنبتاوي',
  NULL,
  '2013-03-10',
  'قرار 1',
  'decision',
  '<p style="text-align:center"><b style="font-size:20px">قرار 1</b></p>
<p>بالرجوع الى برنامج متابعة العملاء الاوتلوك الموكل اليك وبعد المراجعة الحثيثة تبين وجود ثغرات وضعف في المتابعات وادخال البيانات حيث ان البيانات المدخلة تفتقد للدقة المطلوبة لذلك قررت اعفائك ابتداءا من تاريخ 15-03-2013 من ادخال الاوتلوك وتسليم ادخال البيانات الى محمد الجوابرة .</p>
<p>وبالرجوع الى نسب المبيعات خلال الست شهور السابقة قررنا وابتداءا من تاريخ 1-04-2013 سوف يتم احتساب الراتب حسب الجدول المرفق بسبب حجم المبيعات القليل .</p>
',
  'الدكتور محمد عقاب الجوابرة',
  'الادارة',
  true
);

