-- قرار 7.doc  [explicit "التاريخ" line]
INSERT INTO public.official_letters (number, recipient, attention, date, subject, category, body, signer_name, signer_title, use_letterhead)
VALUES (
  (SELECT COALESCE(MAX(number),0)+1 FROM public.official_letters),
  'ابراهيم محمد ابو شمالة',
  NULL,
  '2013-07-15',
  'قرار 7',
  'decision',
  '<p style="text-align:center"><b style="font-size:20px">قرار 7</b></p>
<p>بالرجوع الى كشف الذمم المرفقة ارجو التكرم بالعلم باننا سوف نقوم بقيد الذمم التالية على حسابك لغاية 15-08-2013 اذا لم يتم التحصيل قبل هذا التاريخ سوف يتم تقسيط المبلغ بموجب 5 دفعات لنهاية العام :</p>
<ol>
<li>مؤسسة العرب 500 دينار</li>
<li>جامعة الحسين بن طلال 50 دينار</li>
<li>مديرية زراعة البلقاء 68 دينار</li>
</ol>
<p>وكما نلفت انتباهك الى تحصيل الذمم التالية قبل 30-09-2013 والا سوف يتم قيدها على حسابك :</p>
<ol>
<li>شركة المواد الزراعية والعضوية 35 دينار</li>
<li>مديرية التربية والتعليم للسلط 384 دينار</li>
<li>شركة لين جين 284 دينار</li>
</ol>
',
  'الدكتور محمد عقاب الجوابرة',
  'الادارة',
  true
);

